list_customer_groups.code:
final response = await client.customerGroups.listCustomerGroups(
    queryParams: {'search_text': 'wholesale', 'status': 'active', 'limit': 50});
final body = response.map as Map;
for (final group in body['customer_groups'] as List) {
  print('${(group as Map)['id']} ${group['name']} ${group['status']}');
}
print((body['pagination'] as Map)['has_next']);

