patch_customer_group.code:
final response = await client.customerGroups.patchCustomerGroup(1234, {
  'customer_group': {
    'status': 'inactive',
    'purchase_preference': {
      'minimum_purchase': {'amount': 75},
    },
  },
});
final group = (response.map as Map)['customer_group'] as Map;
final preference = group['purchase_preference'] as Map;
print('${group['status']} ${(preference['minimum_purchase'] as Map)['amount']}');

